describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects bracket with non-positive upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 100, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 100, costCents: 100 }],
            5.5,
          ),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 100, costCents: 100 }],
            -1,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
      { upToGrams: 2000, costCents: 1000 },
    ]);

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 5000)).toBe(0);
    });

    it("returns 0 for zero-weight items", () => {
      expect(calc.computeShippingCents([lineNoWeight("a")], 5000)).toBe(0);
    });

    it("selects the first bracket that covers the weight", () => {
      // 250g → bracket upToGrams=500 → 300
      expect(calc.computeShippingCents([line("a", 250)], 5000)).toBe(300);
    });

    it("selects exact boundary weight bracket", () => {
      // 500g exactly → bracket upToGrams=500 → 300
      expect(calc.computeShippingCents([line("a", 500)], 5000)).toBe(300);
      // 501g → next bracket upToGrams=1000 → 600
      expect(calc.computeShippingCents([line("a", 501)], 5000)).toBe(600);
    });

    it("selects the heaviest bracket for weight at upper boundary", () => {
      // 2000g → bracket upToGrams=2000 → 1000
      expect(calc.computeShippingCents([line("a", 2000)], 5000)).toBe(1000);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      const withOverflow = new WeightBasedShippingCalculator(
        [
          { upToGrams: 500, costCents: 300 },
          { upToGrams: 1000, costCents: 600 },
        ],
        1500,
      );
      expect(withOverflow.computeShippingCents([line("a", 1500)], 5000)).toBe(
        1500,
      );
    });

    it("falls back to heaviest bracket cost when no overflow is set", () => {
      // 3000g exceeds all brackets, no overflow → last bracket cost = 1000
      expect(calc.computeShippingCents([line("a", 3000)], 5000)).toBe(1000);
    });

    it("sorts brackets regardless of input order", () => {
      const unordered = new WeightBasedShippingCalculator([
        { upToGrams: 1000, costCents: 600 },
        { upToGrams: 500, costCents: 300 },
      ]);
      // 250g → should select 500 bracket = 300
      expect(unordered.computeShippingCents([line("a", 250)], 5000)).toBe(300);
    });

    it("sums weight across multiple lines", () => {
      // 2 * 400g = 800g → bracket upToGrams=1000 → 600
      expect(
        calc.computeShippingCents([line("a", 400, 2)], 5000),
      ).toBe(600);
    });
  });
});

