  describe("totals (pricing pipeline)", () => {
    it("computes subtotal as sum of price * quantity", () => {
      const cart = new Cart();
      cart.add(product("a", 500), 3); // 1500
      cart.add(product("b", 1200), 2); // 2400
      const totals = cart.totals();
      expect(totals.subtotalCents).toBe(3900);
    });

    it("applies discount → tax on discounted subtotal → shipping", () => {
      const mockDiscount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(200),
      };
      const mockTax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(80),
      };
      const mockShipping: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(500),
      };

      const cart = new Cart({
        discountPolicy: mockDiscount,
        taxCalculator: mockTax,
        shippingCalculator: mockShipping,
        region: "US-CA",
      });
      cart.add(product("a", 1000), 1);

      const totals = cart.totals();

      expect(totals.subtotalCents).toBe(1000);
      expect(totals.discountCents).toBe(200);
      // Tax called with discounted subtotal (1000-200=800) and region
      expect(mockTax.computeTaxCents).toHaveBeenCalledWith(800, "US-CA");
      expect(totals.taxCents).toBe(80);
      // Shipping called with lines and discounted subtotal
      expect(mockShipping.computeShippingCents).toHaveBeenCalledWith(
        expect.any(Array),
        800,
      );
      expect(totals.shippingCents).toBe(500);
      // total = discounted subtotal + tax + shipping = 800 + 80 + 500
      expect(totals.totalCents).toBe(1380);
    });

    it("clamps discount to [0, subtotal]", () => {
      const overDiscount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(99999),
      };
      const cart = new Cart({ discountPolicy: overDiscount });
      cart.add(product("a", 500), 1);
      const totals = cart.totals();
      expect(totals.discountCents).toBe(500); // clamped to subtotal
      expect(totals.totalCents).toBe(0);
    });

    it("clamps negative discount to 0", () => {
      const negDiscount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(-100),
      };
      const cart = new Cart({ discountPolicy: negDiscount });
      cart.add(product("a", 500), 1);
      expect(cart.totals().discountCents).toBe(0);
    });

    it("clamps negative tax to 0", () => {
      const negTax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(-50),
      };
      const cart = new Cart({ taxCalculator: negTax });
      cart.add(product("a", 500), 1);
      expect(cart.totals().taxCents).toBe(0);
    });

    it("clamps negative shipping to 0", () => {
      const negShipping: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(-100),
      };
      const cart = new Cart({ shippingCalculator: negShipping });
      cart.add(product("a", 500), 1);
      expect(cart.totals().shippingCents).toBe(0);
    });

    it("empty cart returns all zeros", () => {
      const cart = new Cart();
      const totals = cart.totals();
      expect(totals).toEqual({
        subtotalCents: 0,
        discountCents: 0,
        taxCents: 0,
        shippingCents: 0,
        totalCents: 0,
      });
    });

    it("defaults to NoDiscountPolicy, NoTaxCalculator, FreeShippingCalculator, US region", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);
      const totals = cart.totals();
      expect(totals.discountCents).toBe(0);
      expect(totals.taxCents).toBe(0);
      expect(totals.shippingCents).toBe(0);
      expect(totals.totalCents).toBe(1000);
    });
  });

  describe("checkout", () => {
    it("returns totals and lines without collaborators", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(2000);
      expect(result.lines).toHaveLength(1);
      expect(result.lines[0].product.unitPriceCents).toBe(1000);
    });

    describe("price refresh", () => {
      it("updates prices from priceFetcher before computing totals", async () => {
        const cart = new Cart();
        cart.add(product("a", 1000), 1);

        const priceFetcher: PriceFetcher = {
          fetchPriceCents: vi.fn().mockResolvedValue(1500),
        };

        const result = await cart.checkout({ priceFetcher });
        expect(result.totals.subtotalCents).toBe(1500);
        expect(result.lines[0].product.unitPriceCents).toBe(1500);
      });

      it("propagates priceFetcher errors", async () => {
        const cart = new Cart();
        cart.add(product("a", 1000), 1);

        const priceFetcher: PriceFetcher = {
          fetchPriceCents: vi.fn().mockRejectedValue(new Error("service down")),
        };

        await expect(cart.checkout({ priceFetcher })).rejects.toThrow(
          "service down",
        );
      });
    });

    describe("inventory check", () => {
      it("succeeds when inventory is available", async () => {
        const cart = new Cart();
        cart.add(product("a", 1000), 2);

        const inventoryChecker: InventoryChecker = {
          check: vi.fn().mockResolvedValue({ available: true }),
        };

        const result = await cart.checkout({ inventoryChecker });
        expect(result.totals.subtotalCents).toBe(2000);
        expect(inventoryChecker.check).toHaveBeenCalledWith("a", 2);
      });

      it("throws InventoryError when item is unavailable", async () => {
        const cart = new Cart();
        cart.add(product("a", 1000), 5);

        const inventoryChecker: InventoryChecker = {
          check: vi.fn().mockResolvedValue({
            available: false,
            reason: "discontinued",
          }),
        };

        try {
          await cart.checkout({ inventoryChecker });
          expect.unreachable("should have thrown");
        } catch (err) {
          expect(err).toBeInstanceOf(InventoryError);
          const invErr = err as InventoryError;
          expect(invErr.productId).toBe("a");
          expect(invErr.requested).toBe(5);
          expect(invErr.message).toBe("discontinued");
        }
      });

      it("throws InventoryError for partial-stock denial", async () => {
        const cart = new Cart();
        cart.add(product("a", 1000), 10);

        const inventoryChecker: InventoryChecker = {
          check: vi.fn().mockResolvedValue({
            available: true,
            availableQuantity: 3,
          }),
        };

        try {
          await cart.checkout({ inventoryChecker });
          expect.unreachable("should have thrown");
        } catch (err) {
          expect(err).toBeInstanceOf(InventoryError);
          const invErr = err as InventoryError;
          expect(invErr.productId).toBe("a");
          expect(invErr.requested).toBe(10);
          expect(invErr.available).toBe(3);
        }
      });

      it("checks inventory for each line and fails on first denial", async () => {
        const cart = new Cart();
        cart.add(product("a", 1000), 1);
        cart.add(product("b", 2000), 1);

        const inventoryChecker: InventoryChecker = {
          check: vi
            .fn()
            .mockResolvedValueOnce({ available: true })
            .mockResolvedValueOnce({
              available: false,
              reason: "out of stock",
            }),
        };

        await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(
          InventoryError,
        );
      });
    });

    describe("async tax provider", () => {
      it("uses asyncTaxProvider for tax computation", async () => {
        const mockDiscount: DiscountPolicy = {
          computeDiscountCents: vi.fn().mockReturnValue(100),
        };
        const mockShipping: ShippingCalculator = {
          computeShippingCents: vi.fn().mockReturnValue(300),
        };

        const cart = new Cart({
          discountPolicy: mockDiscount,
          shippingCalculator: mockShipping,
          region: "US-CA",
        });
        cart.add(product("a", 1000), 1);

        const asyncTaxProvider: AsyncTaxRateProvider = {
          getRate: vi.fn().mockResolvedValue(0.1),
        };

        const result = await cart.checkout({ asyncTaxProvider });

        // subtotal=1000, discount=100, discounted=900
        // tax = floor(900 * 0.1) = 90
        // shipping = 300
        // total = 900 + 90 + 300 = 1290
        expect(result.totals.subtotalCents).toBe(1000);
        expect(result.totals.discountCents).toBe(100);
        expect(result.totals.taxCents).toBe(90);
        expect(result.totals.shippingCents).toBe(300);
        expect(result.totals.totalCents).toBe(1290);
        expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
      });

      it("propagates async tax provider failure", async () => {
        const cart = new Cart();
        cart.add(product("a", 1000), 1);

        const asyncTaxProvider: AsyncTaxRateProvider = {
          getRate: vi.fn().mockRejectedValue(new Error("rate service error")),
        };

        await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
          "rate service error",
        );
      });
    });

    describe("full pipeline with all collaborators", () => {
      it("refreshes prices, checks inventory, applies async tax", async () => {
        const cart = new Cart({
          discountPolicy: {
            computeDiscountCents: () => 500,
          },
          shippingCalculator: {
            computeShippingCents: () => 200,
          },
          region: "FR",
        });
        cart.add(product("a", 1000), 2);

        const priceFetcher: PriceFetcher = {
          fetchPriceCents: vi.fn().mockResolvedValue(1200),
        };
        const inventoryChecker: InventoryChecker = {
          check: vi.fn().mockResolvedValue({ available: true }),
        };
        const asyncTaxProvider: AsyncTaxRateProvider = {
          getRate: vi.fn().mockResolvedValue(0.2),
        };

        const result = await cart.checkout({
          priceFetcher,
          inventoryChecker,
          asyncTaxProvider,
        });

        // Price refreshed to 1200, qty 2 → subtotal 2400
        // Discount 500, discounted = 1900
        // Tax = floor(1900 * 0.2) = 380
        // Shipping = 200
        // Total = 1900 + 380 + 200 = 2480
        expect(result.totals.subtotalCents).toBe(2400);
        expect(result.totals.discountCents).toBe(500);
        expect(result.totals.taxCents).toBe(380);
        expect(result.totals.shippingCents).toBe(200);
        expect(result.totals.totalCents).toBe(2480);
        expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("a");
        expect(inventoryChecker.check).toHaveBeenCalledWith("a", 2);
        expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("FR");
      });
    });
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([
    [0, 0],
    [1000, 0],
    [-500, 0],
  ])("computeDiscountCents(%i) returns %i", (subtotal, expected) => {
    expect(policy.computeDiscountCents(subtotal)).toBe(expected);
  });
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([
      [-1, "negative"],
      [101, "over 100"],
      [NaN, "NaN"],
      [Infinity, "Infinity"],
    ])("rejects %d (%s)", (percent) => {
      expect(() => new PercentageDiscountPolicy(percent)).toThrow(RangeError);
    });

    it.each([0, 50, 100])("accepts %d", (percent) => {
      expect(() => new PercentageDiscountPolicy(percent)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it.each([
      [10, 1000, 100],
      [25, 999, 249], // floor(999*25/100) = 249.75 → 249
      [50, 1, 0],     // floor(1*50/100) = 0.5 → 0
      [100, 5000, 5000],
      [0, 5000, 0],
    ])("%d%% of %i cents = %i", (percent, subtotal, expected) => {
      const policy = new PercentageDiscountPolicy(percent);
      expect(policy.computeDiscountCents(subtotal)).toBe(expected);
    });

    it("returns 0 when subtotal is zero", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 when subtotal is negative", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([
      [-1, "negative"],
      [3.5, "non-integer"],
    ])("rejects %d (%s)", (amount) => {
      expect(() => new FixedAmountDiscountPolicy(amount)).toThrow(RangeError);
    });

    it("accepts 0", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("caps discount at subtotal when amount exceeds subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(2000);
      expect(policy.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns full amount when subtotal is larger", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(1000)).toBe(500);
    });

    it("returns 0 when subtotal is zero", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 when subtotal is negative", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });
  });
});

describe("CompositeDiscountPolicy", () => {
  it("rejects empty policy list", () => {
    expect(() => new CompositeDiscountPolicy([])).toThrow(
      "CompositeDiscountPolicy requires at least one policy",
    );
  });

  describe("sum mode", () => {
    it("sums discounts from all policies against original subtotal", () => {
      const p1 = new PercentageDiscountPolicy(10); // floor(1000*10/100)=100
      const p2 = new FixedAmountDiscountPolicy(200);
      const composite = new CompositeDiscountPolicy([p1, p2], "sum");
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("clamps negative child results to 0 before summing", () => {
      const negative: any = { computeDiscountCents: () => -50 };
      const fixed = new FixedAmountDiscountPolicy(100);
      const composite = new CompositeDiscountPolicy([negative, fixed], "sum");
      // -50 clamped to 0, plus 100 = 100
      expect(composite.computeDiscountCents(500)).toBe(100);
    });

    it("returns 0 when subtotal is zero", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("defaults to sum mode when not specified", () => {
      const p1 = new FixedAmountDiscountPolicy(100);
      const p2 = new FixedAmountDiscountPolicy(200);
      const composite = new CompositeDiscountPolicy([p1, p2]);
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      // 10% of 1000 = 100, then 10% of 900 = 90 → total 190
      const p1 = new PercentageDiscountPolicy(10);
      const p2 = new PercentageDiscountPolicy(10);
      const composite = new CompositeDiscountPolicy([p1, p2], "chain");
      expect(composite.computeDiscountCents(1000)).toBe(190);
    });

    it("stops accumulating when remaining subtotal reaches 0", () => {
      const p1 = new FixedAmountDiscountPolicy(1000);
      const p2 = new FixedAmountDiscountPolicy(500);
      const composite = new CompositeDiscountPolicy([p1, p2], "chain");
      // p1 takes all 1000, remaining = 0, p2 gets 0
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("ordering matters: larger discount first yields different result", () => {
      const p50 = new PercentageDiscountPolicy(50);
      const fixed200 = new FixedAmountDiscountPolicy(200);

      const bigFirst = new CompositeDiscountPolicy([p50, fixed200], "chain");
      // 50% of 1000=500, then min(200,500)=200 → 700
      expect(bigFirst.computeDiscountCents(1000)).toBe(700);

      const fixedFirst = new CompositeDiscountPolicy([fixed200, p50], "chain");
      // 200 of 1000, then 50% of 800=400 → 600
      expect(fixedFirst.computeDiscountCents(1000)).toBe(600);
    });

    it("returns 0 when subtotal is negative", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(100)],
        "chain",
      );
      expect(composite.computeDiscountCents(-50)).toBe(0);
    });
  });
});

import { describe, it, expect, vi } from "vitest";
import {
  NoTaxCalculator,
  RegionalTaxCalculator,
  AsyncTaxCalculator,
  totalLineWeightGrams,
  type AsyncTaxRateProvider,
} from "../src/tax.ts";
import type { CartLine } from "../src/product.ts";

describe("NoTaxCalculator", () => {
  const calc = new NoTaxCalculator();

  it("always returns 0", () => {
    expect(calc.computeTaxCents(5000, "US")).toBe(0);
    expect(calc.computeTaxCents(0, "FR")).toBe(0);
  });
});

describe("RegionalTaxCalculator", () => {
  describe("constructor validation", () => {
    it("rejects defaultRate out of [0, 1]", () => {
      expect(() => new RegionalTaxCalculator({}, -0.01)).toThrow(RangeError);
      expect(() => new RegionalTaxCalculator({}, 1.01)).toThrow(RangeError);
      expect(() => new RegionalTaxCalculator({}, NaN)).toThrow(RangeError);
    });

    it("rejects individual rate out of [0, 1]", () => {
      expect(() => new RegionalTaxCalculator({ US: 1.5 })).toThrow(RangeError);
      expect(() => new RegionalTaxCalculator({ US: -0.1 })).toThrow(RangeError);
    });

    it("accepts valid rates and defaultRate", () => {
      expect(
        () => new RegionalTaxCalculator({ US: 0.08, FR: 0.2 }, 0.1),
      ).not.toThrow();
    });
  });

  describe("computeTaxCents", () => {
    const calc = new RegionalTaxCalculator(
      { "US-CA": 0.0875, FR: 0.2 },
      0.05,
    );

    it("uses region-specific rate", () => {
      // floor(10000 * 0.0875) = 875
      expect(calc.computeTaxCents(10000, "US-CA")).toBe(875);
    });

    it("falls back to default rate for unknown region", () => {
      // floor(10000 * 0.05) = 500
      expect(calc.computeTaxCents(10000, "DE")).toBe(500);
    });

    it("floors the result", () => {
      // floor(999 * 0.0875) = floor(87.4125) = 87
      expect(calc.computeTaxCents(999, "US-CA")).toBe(87);
    });

    it("returns 0 when taxable is 0 or negative", () => {
      expect(calc.computeTaxCents(0, "US-CA")).toBe(0);
      expect(calc.computeTaxCents(-100, "FR")).toBe(0);
    });

    it("uses 0 as default when no defaultRate specified", () => {
      const c = new RegionalTaxCalculator({ US: 0.1 });
      expect(c.computeTaxCents(1000, "UNKNOWN")).toBe(0);
    });
  });
});

