import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import { InventoryError } from "../src/inventory.ts";

const product = (
  id: string,
  unitPriceCents: number,
  weightGrams?: number,
): Product => ({
  id,
  name: `Product ${id}`,
  unitPriceCents,
  weightGrams,
});

describe("Cart", () => {
  describe("add", () => {
    it("adds a new product", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);
      expect(cart.itemCount).toBe(2);
    });

    it("merges quantity for duplicate product id", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);
      cart.add(product("a", 1000), 3);
      expect(cart.itemCount).toBe(5);
    });

    it("rejects non-positive quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(product("a", 1000), 0)).toThrow(RangeError);
      expect(() => cart.add(product("a", 1000), -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(product("a", 1000), 1.5)).toThrow(RangeError);
    });

    it("rejects negative unit price", () => {
      const cart = new Cart();
      expect(() => cart.add(product("a", -100), 1)).toThrow(RangeError);
    });
  });

  describe("remove", () => {
    it("returns true and removes an existing product", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);
      expect(cart.remove("a")).toBe(true);
      expect(cart.itemCount).toBe(0);
    });

    it("returns false for unknown product id", () => {
      const cart = new Cart();
      expect(cart.remove("nonexistent")).toBe(false);
    });
  });

  describe("updateQuantity", () => {
    it("updates quantity for existing product", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);
      cart.updateQuantity("a", 5);
      expect(cart.itemCount).toBe(5);
    });

    it("removes product when quantity is set to 0", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 3);
      cart.updateQuantity("a", 0);
      expect(cart.itemCount).toBe(0);
    });

    it("throws for unknown product", () => {
      const cart = new Cart();
      expect(() => cart.updateQuantity("nonexistent", 1)).toThrow(
        "Product nonexistent is not in the cart",
      );
    });

    it("throws for negative quantity", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);
      expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
    });

    it("throws for non-integer quantity", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);
      expect(() => cart.updateQuantity("a", 2.5)).toThrow(RangeError);
    });
  });

  describe("clear", () => {
    it("empties the cart", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);
      cart.add(product("b", 2000), 1);
      cart.clear();
      expect(cart.itemCount).toBe(0);
    });
  });

  describe("snapshot", () => {
    it("returns a deep copy that does not affect cart state", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);
      const snap = cart.snapshot();
      snap[0].quantity = 999;
      (snap[0].product as any).unitPriceCents = 0;
      expect(cart.itemCount).toBe(2);
      expect(cart.totals().subtotalCents).toBe(2000);
    });
  });

  describe("totals (pricing pipeline)", () => {
    it("computes subtotal as sum of price * quantity", () => {
      const cart = new Cart();
      cart.add(product("a", 500), 3); // 1500
      cart.add(product("b", 1200), 2); // 2400
      const totals = cart.totals();
      expect(totals.subtotalCents).toBe(3900);
    });

    it("applies discount → tax on discounted subtotal → shipping", () => {
      const mockDiscount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(200),
      };
      const mockTax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(80),
      };
      const mockShipping: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(500),
      };

      const cart = new Cart({
        discountPolicy: mockDiscount,
        taxCalculator: mockTax,
        shippingCalculator: mockShipping,
        region: "US-CA",
      });
      cart.add(product("a", 1000), 1);

      const totals = cart.totals();

      expect(totals.subtotalCents).toBe(1000);
      expect(totals.discountCents).toBe(200);
      // Tax called with discounted subtotal (1000-200=800) and region
      expect(mockTax.computeTaxCents).toHaveBeenCalledWith(800, "US-CA");
      expect(totals.taxCents).toBe(80);
      // Shipping called with lines and discounted subtotal
      expect(mockShipping.computeShippingCents).toHaveBeenCalledWith(
        expect.any(Array),
        800,
      );
      expect(totals.shippingCents).toBe(500);
      // total = discounted subtotal + tax + shipping = 800 + 80 + 500
      expect(totals.totalCents).toBe(1380);
    });

    it("clamps discount to [0, subtotal]", () => {
      const overDiscount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(99999),
      };
      const cart = new Cart({ discountPolicy: overDiscount });
      cart.add(product("a", 500), 1);
      const totals = cart.totals();
      expect(totals.discountCents).toBe(500); // clamped to subtotal
      expect(totals.totalCents).toBe(0);
    });

    it("clamps negative discount to 0", () => {
      const negDiscount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(-100),
      };
      const cart = new Cart({ discountPolicy: negDiscount });
      cart.add(product("a", 500), 1);
      expect(cart.totals().discountCents).toBe(0);
    });

    it("clamps negative tax to 0", () => {
      const negTax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(-50),
      };
      const cart = new Cart({ taxCalculator: negTax });
      cart.add(product("a", 500), 1);
      expect(cart.totals().taxCents).toBe(0);
    });

    it("clamps negative shipping to 0", () => {
      const negShipping: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(-100),
      };
      const cart = new Cart({ shippingCalculator: negShipping });
      cart.add(product("a", 500), 1);
      expect(cart.totals().shippingCents).toBe(0);
    });

    it("empty cart returns all zeros", () => {
      const cart = new Cart();
      const totals = cart.totals();
      expect(totals).toEqual({
        subtotalCents: 0,
        discountCents: 0,
        taxCents: 0,
        shippingCents: 0,
        totalCents: 0,
      });
    });

    it("defaults to NoDiscountPolicy, NoTaxCalculator, FreeShippingCalculator, US region", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);
      const totals = cart.totals();
      expect(totals.discountCents).toBe(0);
      expect(totals.taxCents).toBe(0);
      expect(totals.shippingCents).toBe(0);
      expect(totals.totalCents).toBe(1000);
    });
  });

  describe("checkout", () => {
    it("returns totals and lines without collaborators", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(2000);
      expect(result.lines).toHaveLength(1);
      expect(result.lines[0].product.unitPriceCents).toBe(1000);
    });

    describe("price refresh", () => {
      it("updates prices from priceFetcher before computing totals", async () => {
        const cart = new Cart();
        cart.add(product("a", 1000), 1);

        const priceFetcher: PriceFetcher = {
          fetchPriceCents: vi.fn().mockResolvedValue(1500),
        };

        const result = await cart.checkout({ priceFetcher });
        expect(result.totals.subtotalCents).toBe(1500);
        expect(result.lines[0].product.unitPriceCents).toBe(1500);
      });

      it("propagates priceFetcher errors", async () => {
        const cart = new Cart();
        cart.add(product("a", 1000), 1);

        const priceFetcher: PriceFetcher = {
          fetchPriceCents: vi.fn().mockRejectedValue(new Error("service down")),
        };

        await expect(cart.checkout({ priceFetcher })).rejects.toThrow(
          "service down",
        );
      });
    });

    describe("inventory check", () => {
      it("succeeds when inventory is available", async () => {
        const cart = new Cart();
        cart.add(product("a", 1000), 2);

        const inventoryChecker: InventoryChecker = {
          check: vi.fn().mockResolvedValue({ available: true }),
        };

        const result = await cart.checkout({ inventoryChecker });
        expect(result.totals.subtotalCents).toBe(2000);
        expect(inventoryChecker.check).toHaveBeenCalledWith("a", 2);
      });

      it("throws InventoryError when item is unavailable", async () => {
        const cart = new Cart();
        cart.add(product("a", 1000), 5);

        const inventoryChecker: InventoryChecker = {
          check: vi.fn().mockResolvedValue({
            available: false,
            reason: "discontinued",
          }),
        };

        try {
          await cart.checkout({ inventoryChecker });
          expect.unreachable("should have thrown");
        } catch (err) {
          expect(err).toBeInstanceOf(InventoryError);
          const invErr = err as InventoryError;
          expect(invErr.productId).toBe("a");
          expect(invErr.requested).toBe(5);
          expect(invErr.message).toBe("discontinued");
        }
      });

      it("throws InventoryError for partial-stock denial", async () => {
        const cart = new Cart();
        cart.add(product("a", 1000), 10);

        const inventoryChecker: InventoryChecker = {
          check: vi.fn().mockResolvedValue({
            available: true,
            availableQuantity: 3,
          }),
        };

        try {
          await cart.checkout({ inventoryChecker });
          expect.unreachable("should have thrown");
        } catch (err) {
          expect(err).toBeInstanceOf(InventoryError);
          const invErr = err as InventoryError;
          expect(invErr.productId).toBe("a");
          expect(invErr.requested).toBe(10);
          expect(invErr.available).toBe(3);
        }
      });

      it("checks inventory for each line and fails on first denial", async () => {
        const cart = new Cart();
        cart.add(product("a", 1000), 1);
        cart.add(product("b", 2000), 1);

        const inventoryChecker: InventoryChecker = {
          check: vi
            .fn()
            .mockResolvedValueOnce({ available: true })
            .mockResolvedValueOnce({
              available: false,
              reason: "out of stock",
            }),
        };

        await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(
          InventoryError,
        );
      });
    });

    describe("async tax provider", () => {
      it("uses asyncTaxProvider for tax computation", async () => {
        const mockDiscount: DiscountPolicy = {
          computeDiscountCents: vi.fn().mockReturnValue(100),
        };
        const mockShipping: ShippingCalculator = {
          computeShippingCents: vi.fn().mockReturnValue(300),
        };

        const cart = new Cart({
          discountPolicy: mockDiscount,
          shippingCalculator: mockShipping,
          region: "US-CA",
        });
        cart.add(product("a", 1000), 1);

        const asyncTaxProvider: AsyncTaxRateProvider = {
          getRate: vi.fn().mockResolvedValue(0.1),
        };

        const result = await cart.checkout({ asyncTaxProvider });

        // subtotal=1000, discount=100, discounted=900
        // tax = floor(900 * 0.1) = 90
        // shipping = 300
        // total = 900 + 90 + 300 = 1290
        expect(result.totals.subtotalCents).toBe(1000);
        expect(result.totals.discountCents).toBe(100);
        expect(result.totals.taxCents).toBe(90);
        expect(result.totals.shippingCents).toBe(300);
        expect(result.totals.totalCents).toBe(1290);
        expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
      });

      it("propagates async tax provider failure", async () => {
        const cart = new Cart();
        cart.add(product("a", 1000), 1);

        const asyncTaxProvider: AsyncTaxRateProvider = {
          getRate: vi.fn().mockRejectedValue(new Error("rate service error")),
        };

        await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
          "rate service error",
        );
      });
    });

    describe("full pipeline with all collaborators", () => {
      it("refreshes prices, checks inventory, applies async tax", async () => {
        const cart = new Cart({
          discountPolicy: {
            computeDiscountCents: () => 500,
          },
          shippingCalculator: {
            computeShippingCents: () => 200,
          },
          region: "FR",
        });
        cart.add(product("a", 1000), 2);

        const priceFetcher: PriceFetcher = {
          fetchPriceCents: vi.fn().mockResolvedValue(1200),
        };
        const inventoryChecker: InventoryChecker = {
          check: vi.fn().mockResolvedValue({ available: true }),
        };
        const asyncTaxProvider: AsyncTaxRateProvider = {
          getRate: vi.fn().mockResolvedValue(0.2),
        };

        const result = await cart.checkout({
          priceFetcher,
          inventoryChecker,
          asyncTaxProvider,
        });

        // Price refreshed to 1200, qty 2 → subtotal 2400
        // Discount 500, discounted = 1900
        // Tax = floor(1900 * 0.2) = 380
        // Shipping = 200
        // Total = 1900 + 380 + 200 = 2480
        expect(result.totals.subtotalCents).toBe(2400);
        expect(result.totals.discountCents).toBe(500);
        expect(result.totals.taxCents).toBe(380);
        expect(result.totals.shippingCents).toBe(200);
        expect(result.totals.totalCents).toBe(2480);
        expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("a");
        expect(inventoryChecker.check).toHaveBeenCalledWith("a", 2);
        expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("FR");
      });
    });
  });
});

