          inventoryChecker,
          asyncTaxProvider,
        });

        // Price refreshed to 1200, qty 2 → subtotal 2400
        // Discount 500, discounted = 1900
        // Tax = floor(1900 * 0.2) = 380
        // Shipping = 200
