import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([
    [0, 0],
    [1000, 0],
    [-500, 0],
  ])("computeDiscountCents(%i) returns %i", (subtotal, expected) => {
    expect(policy.computeDiscountCents(subtotal)).toBe(expected);
  });
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([
      [-1, "negative"],
      [101, "over 100"],
      [NaN, "NaN"],
      [Infinity, "Infinity"],
    ])("rejects %d (%s)", (percent) => {
      expect(() => new PercentageDiscountPolicy(percent)).toThrow(RangeError);
    });

    it.each([0, 50, 100])("accepts %d", (percent) => {
      expect(() => new PercentageDiscountPolicy(percent)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it.each([
      [10, 1000, 100],
      [25, 999, 249], // floor(999*25/100) = 249.75 → 249
      [50, 1, 0],     // floor(1*50/100) = 0.5 → 0
      [100, 5000, 5000],
      [0, 5000, 0],
    ])("%d%% of %i cents = %i", (percent, subtotal, expected) => {
      const policy = new PercentageDiscountPolicy(percent);
      expect(policy.computeDiscountCents(subtotal)).toBe(expected);
    });

    it("returns 0 when subtotal is zero", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 when subtotal is negative", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([
      [-1, "negative"],
      [3.5, "non-integer"],
    ])("rejects %d (%s)", (amount) => {
      expect(() => new FixedAmountDiscountPolicy(amount)).toThrow(RangeError);
    });

    it("accepts 0", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("caps discount at subtotal when amount exceeds subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(2000);
      expect(policy.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns full amount when subtotal is larger", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(1000)).toBe(500);
    });

    it("returns 0 when subtotal is zero", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 when subtotal is negative", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });
  });
});

describe("CompositeDiscountPolicy", () => {
  it("rejects empty policy list", () => {
    expect(() => new CompositeDiscountPolicy([])).toThrow(
      "CompositeDiscountPolicy requires at least one policy",
    );
  });

  describe("sum mode", () => {
    it("sums discounts from all policies against original subtotal", () => {
      const p1 = new PercentageDiscountPolicy(10); // floor(1000*10/100)=100
      const p2 = new FixedAmountDiscountPolicy(200);
      const composite = new CompositeDiscountPolicy([p1, p2], "sum");
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("clamps negative child results to 0 before summing", () => {
      const negative: any = { computeDiscountCents: () => -50 };
      const fixed = new FixedAmountDiscountPolicy(100);
      const composite = new CompositeDiscountPolicy([negative, fixed], "sum");
      // -50 clamped to 0, plus 100 = 100
      expect(composite.computeDiscountCents(500)).toBe(100);
    });

    it("returns 0 when subtotal is zero", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("defaults to sum mode when not specified", () => {
      const p1 = new FixedAmountDiscountPolicy(100);
      const p2 = new FixedAmountDiscountPolicy(200);
      const composite = new CompositeDiscountPolicy([p1, p2]);
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      // 10% of 1000 = 100, then 10% of 900 = 90 → total 190
      const p1 = new PercentageDiscountPolicy(10);
      const p2 = new PercentageDiscountPolicy(10);
      const composite = new CompositeDiscountPolicy([p1, p2], "chain");
      expect(composite.computeDiscountCents(1000)).toBe(190);
    });

    it("stops accumulating when remaining subtotal reaches 0", () => {
      const p1 = new FixedAmountDiscountPolicy(1000);
      const p2 = new FixedAmountDiscountPolicy(500);
      const composite = new CompositeDiscountPolicy([p1, p2], "chain");
      // p1 takes all 1000, remaining = 0, p2 gets 0
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("ordering matters: larger discount first yields different result", () => {
      const p50 = new PercentageDiscountPolicy(50);
      const fixed200 = new FixedAmountDiscountPolicy(200);

      const bigFirst = new CompositeDiscountPolicy([p50, fixed200], "chain");
      // 50% of 1000=500, then min(200,500)=200 → 700
      expect(bigFirst.computeDiscountCents(1000)).toBe(700);

      const fixedFirst = new CompositeDiscountPolicy([fixed200, p50], "chain");
      // 200 of 1000, then 50% of 800=400 → 600
      expect(fixedFirst.computeDiscountCents(1000)).toBe(600);
    });

    it("returns 0 when subtotal is negative", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(100)],
        "chain",
      );
      expect(composite.computeDiscountCents(-50)).toBe(0);
    });
  });
});

