+      const p1 = new FixedAmountDiscountPolicy(1000);
+      const p2 = new FixedAmountDiscountPolicy(500);
+      const composite = new CompositeDiscountPolicy([p1, p2], "chain");
+      // p1 takes all 1000, remaining = 0, p2 gets 0
+      expect(composite.computeDiscountCents(1000)).toBe(1000);
+    });
+
+    it("ordering matters: larger discount first yields different result", () => {
+      const p50 = new PercentageDiscountPolicy(50);
+      const fixed200 = new FixedAmountDiscountPolicy(200);
+
+      const bigFirst = new CompositeDiscountPolicy([p50, fixed200], "chain");
+      // 50% of 1000=500, then min(200,500)=200 → 700
+      expect(bigFirst.computeDiscountCents(1000)).toBe(700);
+
+      const fixedFirst = new CompositeDiscountPolicy([fixed200, p50], "chain");
+      // 200 of 1000, then 50% of 800=400 → 600
+      expect(fixedFirst.computeDiscountCents(1000)).toBe(600);
+    });
+
+    it("returns 0 when subtotal is negative", () => {
+      const composite = new CompositeDiscountPolicy(
+        [new FixedAmountDiscountPolicy(100)],
+        "chain",
+      );
+      expect(composite.computeDiscountCents(-50)).toBe(0);
+    });
+  });
